parameters.cypherQuery:
CALL {
  MATCH (f:ProcessedFile)
  RETURN collect({name: f.name, hash: f.hash}) AS files
}
CALL {
  MATCH (n) WHERE n.hash IS NOT NULL
  RETURN collect(distinct n.hash) AS hashes
}
RETURN files AS existing_files, hashes AS existing_hashes

parameters.jsCode:
const items = $input.all();
const results = [];
const BATCH_SIZE = 5;

function getHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash;
  }
  return (hash >>> 0).toString(16);
}

const existingFiles = new Map();
const existingRowHashes = new Set();
try {
  const fetchNode = $('Fetch Ingested Entities').first()?.json || {};
  const files = fetchNode.existing_files || [];
  files.forEach(item => {
    if (item && item.name) existingFiles.set(item.name, item.hash || '');
  });
  const hashes = fetchNode.existing_hashes || [];
  hashes.forEach(h => {
    if (h) existingRowHashes.add(h);
  });
} catch (e) {
  console.warn('Could not read existing files or hashes:', e);
}

function parseCSV(text) {
  const lines = text.split(/\r?\n/);
  if (lines.length === 0) return [];
  const headers = parseCSVLine(lines[0]);
  const rows = [];
  for (let i = 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    const values = parseCSVLine(lines[i]);
    const row = {};
    headers.forEach((header, idx) => { row[header] = values[idx] || ''; });
    rows.push(row);
  }
  return rows;
}

function parseCSVLine(line) {
  const result = [];
  let current = '';
  let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    if (char === '"') { inQuotes = !inQuotes; }
    else if (char === ',' && !inQuotes) { result.push(current.trim()); current = ''; }
    else { current += char; }
  }
  result.push(current.trim());
  return result;
}

const entityRules = `IMPORTANT ENTITY RESOLUTION RULES:
1. ENTITY RESOLUTION: Map raw names to existing IDs by checking the "Existing DB Entities" list provided dynamically at runtime. If a name/entity matches an existing database entity semantically (e.g. ignoring minor spelling differences, casing, abbreviations, or company suffixes like "GmbH" or "Corp"), you MUST map it to that existing canonical ID.
2. PROCESS IDs: For Process entities, ALWAYS use the compound ID format <unit_id>_<process_id> (e.g., EVC-2024-0001_P01) as their canonical_id. Never use just 'P01' or 'P02' alone.
3. NEW ENTITY ID RULES: If an entity is not present in the existing database, generate a new canonical ID following these patterns:
   - For Actors: A<n> (increment from the highest A number in the existing DB, e.g., A18).
   - For Locations: LOC_<3-LETTER-COUNTRY-CODE> (e.g., LOC_GER, LOC_VIE).
   - For Products/ChargingStations: EVC-<year>-<n> (or product-specific ID).
   - For Materials: MAT_<n>.
   - For other custom types: Use the label type as prefix, e.g., RISK_<n>.
4. ENTITY MERGING: Variations of same name (e.g. 'Germany' and 'DE') get SAME ID.
5. PROPERTIES: Extract ALL relevant fields/attributes from the raw record and include them in the 'properties' dictionary of the entity or relationship (e.g. cost_eur, duration_days, start_date, completion_date, status, serial_number, product_variant, manufacture_date, country, distance_km, carbon_kg_co2_eq). Keep key names exactly as they appear in the raw records.

Entity types: Actor, Location, ChargingStation, Process, Material, Risk, MaintenanceEvent, TestReport, IncidentReport, AuditFinding, or other relevant supply chain labels based on the input dataset.
Relationship types: LOCATED_IN, EXECUTED_BY, UNDERGOES, SUPPLIES, USES_MATERIAL, TESTED_BY, MAINTAINED_BY, RELATED_TO, MITIGATES, CAUSED_BY, DETECTED_IN, or other relevant relationship types.

OUTPUT FORMAT (JSON):
You MUST output ONLY a valid JSON object with no markdown:
{
  "entities": [
    { "entity_type": "Actor", "canonical_id": "A1", "properties": { "name": "Steel Supplier Alpha", "country": "Germany" } }
  ],
  "relationships": [
    { "from_type": "Actor", "from_id": "A1", "relationship_type": "LOCATED_IN", "to_type": "Location", "to_id": "LOC_GER", "properties": {} }
  ]
}`;

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  if (!item.binary) continue;

  for (const [key, binaryData] of Object.entries(item.binary)) {
    const fileName = binaryData.fileName || 'unknown';
    if (fileName.toLowerCase().endsWith(".csv")) {
      console.log(`Skipping CSV ${fileName} in LLM extraction because CSVs are imported deterministically.`);
      continue;
    }
    if (!/^.*\.(txt|md|html)$/i.test(fileName)) {
      console.log(`Skipping non-data file: ${fileName}`);
      continue;
    }

    const ext = fileName.split('.').pop().toLowerCase();

    if (ext === "csv") {
      console.log(`Skipping CSV ${fileName} in LLM extraction because CSVs are imported deterministically.`);
      continue;
    }

    const buffer = await this.helpers.getBinaryDataBuffer(i, key);
    const text = buffer.toString('utf-8').replace(/\r\n/g, '\n');
    const fileHash = getHash(text);

    // File-level cache check
    if (existingFiles.has(fileName)) {
      const storedFileHash = existingFiles.get(fileName);
      if (!storedFileHash || storedFileHash === fileHash) {
        console.log(`Skipping file ${fileName} (cache hit).`);
        continue;
      }
    }

    const fileResults = [];
    if (ext === 'csv') {
      const allRows = parseCSV(text);
      let newBatchesCount = 0;

      // BATCH rows into groups of BATCH_SIZE
      for (let batchStart = 0; batchStart < allRows.length; batchStart += BATCH_SIZE) {
        const batch = allRows.slice(batchStart, batchStart + BATCH_SIZE);
        const batchTexts = batch.map((row, idx) => {
          const rowText = Object.entries(row)
            .filter(([k, v]) => v !== null && v !== undefined && v !== '')
            .map(([k, v]) => `${k}: ${v}`)
            .join('\n');
          return `--- Row ${batchStart + idx + 1} ---\n${rowText}`;
        });

        // Use the hash of the batch content to identify it uniquely
        const batchHash = getHash(batchTexts.join('|||'));

        // Check if this batch is already ingested
        if (existingRowHashes.has(batchHash)) {
          console.log(`Skipping batch ${batchStart+1}-${batchStart+batch.length} of file ${fileName} (cache hit).`);
          continue;
        }

        newBatchesCount++;
        const prompt = `Analyze these ${batch.length} supply chain records from file ${fileName} (rows ${batchStart+1}-${batchStart+batch.length}):\n\n${batchTexts.join('\n\n')}\n\n${entityRules}`;

        fileResults.push({
          json: {
            fileName: fileName,
            fileType: ext,
            batchStart: batchStart + 1,
            batchEnd: batchStart + batch.length,
            batchSize: batch.length,
            prompt: prompt,
            rowHash: batchHash,
            fileHash: fileHash,
            isLastBatch: false
          }
        });
      }
      console.log(`File ${fileName}: ${allRows.length} total rows -> ${newBatchesCount} new/changed batches to process.`);
    } else {
      // Unstructured files: send as single item
      const docHash = getHash(text);
      if (existingRowHashes.has(docHash)) {
        console.log(`Unstructured file ${fileName} already ingested. Skipping.`);
        continue;
      }
      const prompt = `Analyze this supply chain unstructured document from file ${fileName}:\n${text}\n\n${entityRules}`;
      fileResults.push({
        json: {
          fileName: fileName,
          fileType: ext,
          prompt: prompt,
          rowHash: docHash,
          fileHash: fileHash,
          isLastBatch: false
        }
      });
    }

    if (fileResults.length > 0) {
      fileResults[fileResults.length - 1].json.isLastBatch = true;
      results.push(...fileResults);
    }
  }
}

console.log("Total items to process: " + results.length);
if (results.length === 0) {
  return [{ json: { skippedAll: true } }];
}
return results;

parameters.cypherQuery:
CALL { MATCH (a:Actor) RETURN collect({id: a.actor_id, name: a.actor_name}) AS actors }
CALL { MATCH (l:Location) RETURN collect({code: l.location_code, name: l.location_name, country: l.country}) AS locations }
CALL { MATCH (cs:ChargingStation) RETURN collect({id: cs.unit_id, model: cs.model}) AS stations }
CALL { MATCH (m:Material) RETURN collect({id: m.material_id, name: m.material_name}) AS materials }
RETURN actors AS db_actors, locations AS db_locations, stations AS db_stations, materials AS db_materials

parameters.jsCode:
const items = $input.all();
const queries = [];

for (const item of items) {
  let outputStr = item.json.text || '';
  if (!outputStr && item.json.choices && item.json.choices[0] && item.json.choices[0].message) {
    outputStr = item.json.choices[0].message.content || '';
  }

  // Skip error/empty responses
  if (!outputStr || outputStr.trim() === '') {
    console.warn('Empty LLM response, skipping');
    continue;
  }

  // Strip thinking tags if present
  outputStr = outputStr.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();

  // Clean markdown backticks
  outputStr = outputStr.replace(/^\s*```(json)?/mi, '').replace(/```\s*$/m, '').trim();

  let output = {};
  try {
    output = JSON.parse(outputStr);
  } catch(e) {
    const jsonMatch = outputStr.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      try {
        output = JSON.parse(jsonMatch[0]);
      } catch(e2) {
        console.warn('Failed to parse JSON output from LLM:', e2.message);
        continue;
      }
    } else {
      console.warn('No JSON found in LLM output');
      continue;
    }
  }

  const entities = output.entities || [];
  const relationships = output.relationships || [];

  let fileName = 'unknown';
  let rowHash = '';
  let fileHash = '';
  try {
    const rawItem = $('Loop Raw Items').item.json;
    fileName = rawItem.fileName || 'unknown';
    rowHash = rawItem.rowHash || '';
    fileHash = rawItem.fileHash || '';
  } catch(e) {
    console.warn('Could not read from Loop Raw Items:', e);
  }

  const clauses = [];
  let varIdx = 0;

  for (const entity of entities) {
    const label = entity.entity_type;
    const id = entity.canonical_id;
    const props = entity.properties || {};

    if (!label || !id) continue;

    const idField = label === 'Actor' ? 'actor_id' :
                   label === 'Location' ? 'location_code' :
                   label === 'ChargingStation' ? 'unit_id' :
                   label === 'Process' ? 'process_id' :
                   label === 'Material' ? 'material_id' : 'id';

    const v = `n${varIdx++}`;
    const setParts = Object.entries(props)
      .filter(([k, val]) => val !== null && val !== undefined && val !== '' && k !== idField)
      .map(([k, val]) => {
        const safeKey = k.replace(/`/g, '\\`');
        if (typeof val === 'number' || typeof val === 'boolean') {
          return `${v}.\`${safeKey}\` = ${val}`;
        }
        const safeVal = String(val).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
        return `${v}.\`${safeKey}\` = '${safeVal}'`;
      });
    setParts.push(`${v}.ingested_at = datetime('${new Date().toISOString()}')`);
    setParts.push(`${v}.source_file = '${fileName}'`);
    setParts.push(`${v}.hash = '${rowHash || fileHash}'`);

    const safeId = String(id).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
    clauses.push(`MERGE (${v}:${label} {${idField}: '${safeId}'}) SET ${setParts.join(', ')}`);
  }

  for (const rel of relationships) {
    if (!rel.from_type || !rel.from_id || !rel.to_type || !rel.to_id || !rel.relationship_type) continue;

    const fromField = rel.from_type === 'Actor' ? 'actor_id' :
                      rel.from_type === 'Location' ? 'location_code' :
                      rel.from_type === 'ChargingStation' ? 'unit_id' :
                      rel.from_type === 'Process' ? 'process_id' :
                      rel.from_type === 'Material' ? 'material_id' : 'id';
    const toField = rel.to_type === 'Actor' ? 'actor_id' :
                    rel.to_type === 'Location' ? 'location_code' :
                    rel.to_type === 'ChargingStation' ? 'unit_id' :
                    rel.to_type === 'Process' ? 'process_id' :
                    rel.to_type === 'Material' ? 'material_id' : 'id';

    const relProps = rel.properties || {};
    const relSetParts = [];
    const relVar = `r${varIdx++}`;
    const fromVar = `a${varIdx++}`;
    const toVar = `b${varIdx++}`;

    Object.entries(relProps)
      .filter(([k, val]) => val !== null && val !== undefined)
      .forEach(([k, val]) => {
        const safeKey = k.replace(/`/g, '\\`');
        if (typeof val === 'number' || typeof val === 'boolean') {
          relSetParts.push(`${relVar}.\`${safeKey}\` = ${val}`);
        } else {
          const safeVal = String(val).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
          relSetParts.push(`${relVar}.\`${safeKey}\` = '${safeVal}'`);
        }
      });
    relSetParts.push(`${relVar}.ingested_at = datetime('${new Date().toISOString()}')`);
    relSetParts.push(`${relVar}.source_file = '${fileName}'`);

    const setClause = relSetParts.length > 0 ? ' SET ' + relSetParts.join(', ') : '';
    const safeFromId = String(rel.from_id).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
    const safeToId = String(rel.to_id).replace(/\\/g, '\\\\').replace(/'/g, "\\'");

    clauses.push(`WITH 1 AS dummy MATCH (${fromVar}:${rel.from_type} {${fromField}: '${safeFromId}'}) MATCH (${toVar}:${rel.to_type} {${toField}: '${safeToId}'}) MERGE (${fromVar})-[${relVar}:${rel.relationship_type}]->(${toVar})${setClause}`);
  }

  if (clauses.length > 0) {
    const fullQuery = clauses.join('\n') + '\nRETURN 1 AS ok';
    queries.push({ json: { queryType: 'batch', cypher: fullQuery } });
  }
}

if (queries.length === 0) {
  queries.push({ json: { queryType: 'noop', cypher: 'RETURN 1 AS ok' } });
}

return queries;

const loopItems = $('Loop Raw Items').all();
let llm1Items = [];
try {
  llm1Items = $('LLM Call 1: Create Prompt').all();
} catch (e) {}
let llm2Items = [];
try {
  llm2Items = $('LLM Call 2: Extract Entities').all();
} catch (e) {}

const failedFiles = new Set();

// Check LLM 1 errors
for (let i = 0; i < llm1Items.length; i++) {
  const item = llm1Items[i];
  if (item.json.error) {
    const loopJson = loopItems[i]?.json || {};
    if (loopJson.fileName) failedFiles.add(loopJson.fileName);
  }
}

// Check LLM 2 errors
for (let i = 0; i < llm2Items.length; i++) {
  const item = llm2Items[i];
  if (item.json.error || !item.json.choices || !item.json.choices[0] || !item.json.choices[0].message || !item.json.choices[0].message.content) {
    const loopJson = loopItems[i]?.json || {};
    if (loopJson.fileName) failedFiles.add(loopJson.fileName);
  }
}

const items = $('Extract File Content').all();
const uniqueFiles = [];
const seen = new Set();
for (const item of items) {
  const json = item.json;
  if (json.fileName && json.fileHash && !seen.has(json.fileName) && !failedFiles.has(json.fileName)) {
    seen.add(json.fileName);
    uniqueFiles.push({ name: json.fileName, hash: json.fileHash });
  }
}
if (uniqueFiles.length === 0) {
  return [{ json: { query: "RETURN 1 AS ok" } }];
}
const mapStrings = uniqueFiles.map(f => `{name: '${f.name.replace(/'/g, "\\'")}', hash: '${f.hash}'}`).join(", ");
const query = `UNWIND [${mapStrings}] AS f MERGE (file:ProcessedFile {name: f.name}) SET file.hash = f.hash, file.ingested_at = datetime() RETURN file.name`;
return [{ json: { query } }];

const prompt = $('Loop Raw Items').item.json.prompt || "";
const db_actors = $json.db_actors || [];
const db_locations = $json.db_locations || [];
const db_stations = $json.db_stations || [];
const db_materials = $json.db_materials || [];

const payload = {
  model: "google/gemma-4-31B-it",
  messages: [
    {
      role: "system",
      content: "You are a database entity resolution assistant for a supply chain knowledge graph. Your task is to analyze raw input records and compare them against the provided \"Existing DB Entities\" list. Decide which names match existing entities and must map to those existing IDs (accounting for typos, abbreviations, casing, or company suffixes like GmbH/Corp), and which require generating new IDs according to the rules (Actors=A<n>, Locations=LOC_<3-LETTER>, ChargingStations=EVC-<year>-<n>, Materials=MAT_<n>, Processes=<unit_id>_<process_id>). Output ONLY a bulleted list of mapping rules, no markdown code block wrapper, no conversational text."
    },
    {
      role: "user",
      content: `Raw Record:\n${prompt}\n\nExisting DB Entities:\n- Actors: ${JSON.stringify(db_actors)}\n- Locations: ${JSON.stringify(db_locations)}\n- Stations: ${JSON.stringify(db_stations)}\n- Materials: ${JSON.stringify(db_materials)}`
    }
  ],
  temperature: 0.1,
  max_tokens: 4096
};

return [{ json: payload }];

const llm1_output = $json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content ? $json.choices[0].message.content : "";
const prompt = $('Loop Raw Items').item.json.prompt || "";

const payload = {
  model: "google/gemma-4-31B-it",
  messages: [
    {
      role: "system",
      content: "You are a precise supply chain knowledge graph entity extractor. Extract ALL entities and relationships from the input. Use the provided Mapping Instructions to resolve canonical IDs. Extract all attributes (e.g. cost_eur, duration_days, start_date, completion_date, status, serial_number, product_variant, manufacture_date, country, distance_km, carbon_kg_co2_eq) in the properties dictionary using the raw record field names as keys. Output ONLY valid JSON conforming strictly to the schema (no markdown backticks, no thinking tags). Schema: {\"entities\": [{\"entity_type\": \"Actor\"|\"Location\"|\"ChargingStation\"|\"Process\"|\"Material\"|\"Risk\"|\"MaintenanceEvent\"|\"TestReport\"|\"IncidentReport\"|\"AuditFinding\"|or any other relevant supply chain label, \"canonical_id\": \"ID\", \"properties\": {\"name\": \"...\", ...}}], \"relationships\": [{\"from_type\": \"...\", \"from_id\": \"...\", \"relationship_type\": \"LOCATED_IN\"|\"EXECUTED_BY\"|\"UNDERGOES\"|\"SUPPLIES\"|\"USES_MATERIAL\"|\"TESTED_BY\"|\"MAINTAINED_BY\"|\"RELATED_TO\"|or any other relevant relationship type, \"to_type\": \"...\", \"to_id\": \"...\", \"properties\": {}}]}"
    },
    {
      role: "user",
      content: `Mapping Instructions:\n${llm1_output}\n\nRaw Record to Extract:\n${prompt}`
    }
  ],
  temperature: 0.1,
  max_tokens: 8192
};

return [{ json: payload }];

const items = $input.all();

function getHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash;
  }
  return (hash >>> 0).toString(16);
}

function cleanValue(value) {
  return String(value || "")
    .trim()
    .replace(/^"+|"+$/g, "")
    .replace(/\\"/g, "")
    .replace(/""/g, '"')
    .trim();
}

function normalizeHeader(header) {
  return cleanValue(header)
    .replace(/\s+/g, "_")
    .replace(/[^a-zA-Z0-9_]/g, "")
    .toLowerCase();
}

function parseCSV(text) {
  const lines = text.split(/\r?\n/).filter((line) => line.trim());
  if (lines.length === 0) return [];

  const headers = parseCSVLine(lines[0]).map(normalizeHeader);
  const rows = [];

  for (let i = 1; i < lines.length; i++) {
    const values = parseCSVLine(lines[i]);
    const row = {};

    headers.forEach((header, index) => {
      row[header] = cleanValue(values[index] || "");
    });

    rows.push(row);
  }

  return rows;
}

function parseCSVLine(line) {
  const result = [];
  let current = "";
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];

    if (char === '"') {
      inQuotes = !inQuotes;
    } else if (char === "," && !inQuotes) {
      result.push(current);
      current = "";
    } else {
      current += char;
    }
  }

  result.push(current);
  return result;
}

function toPascalCase(value) {
  return String(value)
    .replace(/^\d+_/, "")
    .replace(/\.[^.]+$/, "")
    .replace(/[^a-zA-Z0-9]+/g, " ")
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
    .join("");
}

function singularize(label) {
  if (label.endsWith("ies")) return label.slice(0, -3) + "y";
  if (label.endsWith("ses")) return label.slice(0, -2);
  if (label.endsWith("s") && !label.endsWith("ss")) return label.slice(0, -1);
  return label;
}

function inferLabelFromFile(fileName) {
  const baseName = fileName
    .replace(/\.[^.]+$/, "")
    .replace(/^\d+_/, "")
    .replace(/^erp_/, "")
    .replace(/^sample_/, "");

  return singularize(toPascalCase(baseName));
}

function inferPrimaryKey(rows, label) {
  if (!rows.length) return "id";

  const keys = Object.keys(rows[0]);
  const lowerLabel = label.toLowerCase();

  const preferred = [
    "id",
    `${lowerLabel}_id`,
    "unit_id",
    "actor_id",
    "material_id",
    "location_code",
    "process_id",
    "transport_id",
    "po_number",
    "production_order",
    "document_id",
    "notification_id",
    "maintenance_id",
    "test_report_id",
    "serial_number",
    "name",
  ];

  for (const candidate of preferred) {
    if (keys.includes(candidate)) return candidate;
  }

  const idLike = keys.find((key) => key.endsWith("_id") || key.includes("id"));
  if (idLike) return idLike;

  return "_entity_id";
}

function safeNeo4jIdentifier(value, fallback = "UnknownEntity") {
  const cleaned = String(value || "").replace(/[^a-zA-Z0-9_]/g, "");

  if (!cleaned) return fallback;
  if (/^[0-9]/.test(cleaned)) return `${fallback}${cleaned}`;

  return cleaned;
}

function safeRelType(value) {
  return String(value || "RELATED_TO")
    .replace(/[^a-zA-Z0-9_]/g, "_")
    .toUpperCase();
}

function normalizeValue(value) {
  if (value === "") return null;

  if (/^-?\d+$/.test(value)) return Number.parseInt(value, 10);
  if (/^-?\d+\.\d+$/.test(value)) return Number.parseFloat(value);

  return value;
}

function buildEntityId(row, idFields, fallbackPrefix, index) {
  if (Array.isArray(idFields) && idFields.length > 0) {
    const value = idFields
      .map((field) => row[field])
      .filter((value) => value !== null && value !== undefined && value !== "")
      .join("|");

    if (value) return value;
  }

  return `${fallbackPrefix}_${index + 1}`;
}

function normalizeRows(rawRows, config, label, fileName) {
  const rows = [];

  for (let index = 0; index < rawRows.length; index++) {
    const rawRow = rawRows[index];
    const row = {};

    for (const [key, value] of Object.entries(rawRow)) {
      row[key] = normalizeValue(value);
    }

    if (Array.isArray(config.idFields) && config.idFields.length > 0) {
      row._entity_id = buildEntityId(row, config.idFields, label, index);
    }

    if (!row._entity_id) {
      row._entity_id = `${fileName}:${index + 1}`;
    }

    rows.push(row);
  }

  return rows;
}

/**
 * Generic entity configuration.
 *
 * isMasterEntity = true means:
 * - This CSV represents the canonical/master list for that entity type.
 * - Example: 01_charging_stations.csv creates canonical ChargingStation nodes.
 *
 * isMasterEntity = false means:
 * - This CSV represents transactions, logs, reports, movements, or events.
