const output = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];

  if (!item.binary) continue;

  for (const [key, binaryData] of Object.entries(item.binary)) {
    const fileName = binaryData.fileName || "unknown.csv";

    if (!fileName.toLowerCase().endsWith(".csv")) {
      continue;
    }

    const buffer = await this.helpers.getBinaryDataBuffer(i, key);
    const text = buffer.toString("utf-8").replace(/\r\n/g, "\n");
    const fileHash = getHash(text);

    const rawRows = parseCSV(text);
    if (rawRows.length === 0) continue;

    const config = ENTITY_CONFIG[fileName] || {};

    const label = safeNeo4jIdentifier(
      config.label || inferLabelFromFile(fileName)
    );

    const primaryKey = config.primaryKey || inferPrimaryKey(rawRows, label);
    const displayNameKey = config.displayNameKey || primaryKey;
    const isMasterEntity = config.isMasterEntity === true;

    const relationships = Array.isArray(config.relationships)
      ? config.relationships.map((rel) => ({
          fromKey: rel.fromKey,
          toLabel: safeNeo4jIdentifier(rel.toLabel, "TargetEntity"),
          toKey: rel.toKey,
          type: safeRelType(rel.type),
        }))
      : [];

    const rows = normalizeRows(rawRows, config, label, fileName).filter(
      (row) => row[primaryKey] !== null && row[primaryKey] !== undefined
    );

    if (rows.length === 0) continue;

    const mergeProperties = Array.isArray(config.idFields) && config.idFields.length > 0
      ? config.idFields.map(f => "\`" + f + "\`: row." + f).join(", ")
      : "\`" + primaryKey + "\`: row[$primaryKey]";

    const query = `
UNWIND $rows AS row
MERGE (n:${label} {${mergeProperties}})
SET n += row,
    n.display_name = coalesce(row[$displayNameKey], row[$primaryKey]),
    n.source_file = $fileName,
    n.source_table = $fileName,
    n.entity_label = $label,
    n.primary_key = $primaryKey,
    n.is_master_record = $isMasterEntity,
    n.hash = $fileHash,
    n.ingested_at = datetime()

WITH n, row

CALL {
  WITH n, row
  UNWIND $relationships AS relConfig
  WITH n, row, relConfig
  WHERE row[relConfig.fromKey] IS NOT NULL

  WITH n,
       relConfig.toLabel AS targetLabel,
       relConfig.toKey AS targetKey,
       relConfig.type AS relationshipType,
       row[relConfig.fromKey] AS targetId

  WITH n,
       targetLabel,
       targetKey,
       relationshipType,
       targetId,
       apoc.map.fromPairs([[targetKey, targetId]]) AS targetIdentity

  CALL apoc.merge.node(
    [targetLabel],
    targetIdentity,
    {
      display_name: toString(targetId),
      source_file: $fileName,
      is_master_record: false,
      ingested_at: datetime()
    },
    {}
  ) YIELD node AS targetNode

  CALL apoc.merge.relationship(
    n,
    relationshipType,
    {},
    {
      source_file: $fileName,
      ingested_at: datetime()
    },
    targetNode
  ) YIELD rel

  RETURN count(rel) AS rel_count
}

WITH count(n) AS imported_count

MERGE (file:ProcessedFile {name: $fileName})
SET file.hash = $fileHash,
    file.entity_label = $label,
    file.primary_key = $primaryKey,
    file.is_master_entity = $isMasterEntity,
    file.ingested_at = datetime()

RETURN
  $fileName AS file_name,
  $label AS entity_label,
  $primaryKey AS primary_key,
  $isMasterEntity AS is_master_entity,
  $chunkNumber AS chunk_number,
  $chunkStart AS chunk_start,
  $chunkEnd AS chunk_end,
  imported_count
`;

    const CHUNK_SIZE = 25;

    for (let start = 0; start < rows.length; start += CHUNK_SIZE) {
      const chunkRows = rows.slice(start, start + CHUNK_SIZE);
      const chunkNumber = Math.floor(start / CHUNK_SIZE) + 1;

      output.push({
        json: {
          query,
          params: {
            rows: chunkRows,
            fileName,
            fileHash,
            label,
            primaryKey,
            displayNameKey,
            isMasterEntity,
            relationships,
            chunkNumber,
            chunkStart: start + 1,
            chunkEnd: start + chunkRows.length,
          },
        },
      });
    }
  }
}

return output;

