const items = $input.all();
const queries = [];

for (const item of items) {
  let outputStr = item.json.text || '';
  if (!outputStr && item.json.choices && item.json.choices[0] && item.json.choices[0].message) {
    outputStr = item.json.choices[0].message.content || '';
  }

  // Skip error/empty responses
  if (!outputStr || outputStr.trim() === '') {
    console.warn('Empty LLM response, skipping');
    continue;
  }

  // Strip thinking tags if present
  outputStr = outputStr.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();

  // Clean markdown backticks
  outputStr = outputStr.replace(/^\s*```(json)?/mi, '').replace(/```\s*$/m, '').trim();

  let output = {};
  try {
    output = JSON.parse(outputStr);
  } catch(e) {
    const jsonMatch = outputStr.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      try {
        output = JSON.parse(jsonMatch[0]);
      } catch(e2) {
        console.warn('Failed to parse JSON output from LLM:', e2.message);
        continue;
      }
    } else {
      console.warn('No JSON found in LLM output');
      continue;
    }
  }

  const entities = output.entities || [];
  const relationships = output.relationships || [];

  let fileName = 'unknown';
  let rowHash = '';
  let fileHash = '';
  try {
    const rawItem = $('Loop Raw Items').item.json;
    fileName = rawItem.fileName || 'unknown';
    rowHash = rawItem.rowHash || '';
    fileHash = rawItem.fileHash || '';
  } catch(e) {
    console.warn('Could not read from Loop Raw Items:', e);
  }

  const clauses = [];
  let varIdx = 0;

  for (const entity of entities) {
    const label = entity.entity_type;
    const id = entity.canonical_id;
    const props = entity.properties || {};

    if (!label || !id) continue;

    const idField = label === 'Actor' ? 'actor_id' :
                   label === 'Location' ? 'location_code' :
                   label === 'ChargingStation' ? 'unit_id' :
                   label === 'Process' ? 'process_id' :
                   label === 'Material' ? 'material_id' : 'id';

    const v = `n${varIdx++}`;
    const setParts = Object.entries(props)
      .filter(([k, val]) => val !== null && val !== undefined && val !== '' && k !== idField)
      .map(([k, val]) => {
        const safeKey = k.replace(/`/g, '\\`');
        if (typeof val === 'number' || typeof val === 'boolean') {
          return `${v}.\`${safeKey}\` = ${val}`;
        }
        const safeVal = String(val).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
        return `${v}.\`${safeKey}\` = '${safeVal}'`;
      });
    setParts.push(`${v}.ingested_at = datetime('${new Date().toISOString()}')`);
    setParts.push(`${v}.source_file = '${fileName}'`);
    setParts.push(`${v}.hash = '${rowHash || fileHash}'`);

    const safeId = String(id).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
    clauses.push(`MERGE (${v}:${label} {${idField}: '${safeId}'}) SET ${setParts.join(', ')}`);
  }

  for (const rel of relationships) {
    if (!rel.from_type || !rel.from_id || !rel.to_type || !rel.to_id || !rel.relationship_type) continue;

    const fromField = rel.from_type === 'Actor' ? 'actor_id' :
                      rel.from_type === 'Location' ? 'location_code' :
                      rel.from_type === 'ChargingStation' ? 'unit_id' :
                      rel.from_type === 'Process' ? 'process_id' :
                      rel.from_type === 'Material' ? 'material_id' : 'id';
    const toField = rel.to_type === 'Actor' ? 'actor_id' :
                    rel.to_type === 'Location' ? 'location_code' :
                    rel.to_type === 'ChargingStation' ? 'unit_id' :
                    rel.to_type === 'Process' ? 'process_id' :
                    rel.to_type === 'Material' ? 'material_id' : 'id';

    const relProps = rel.properties || {};
    const relSetParts = [];
    const relVar = `r${varIdx++}`;
    const fromVar = `a${varIdx++}`;
    const toVar = `b${varIdx++}`;

    Object.entries(relProps)
      .filter(([k, val]) => val !== null && val !== undefined)
      .forEach(([k, val]) => {
        const safeKey = k.replace(/`/g, '\\`');
        if (typeof val === 'number' || typeof val === 'boolean') {
          relSetParts.push(`${relVar}.\`${safeKey}\` = ${val}`);
        } else {
          const safeVal = String(val).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
          relSetParts.push(`${relVar}.\`${safeKey}\` = '${safeVal}'`);
        }
      });
    relSetParts.push(`${relVar}.ingested_at = datetime('${new Date().toISOString()}')`);
    relSetParts.push(`${relVar}.source_file = '${fileName}'`);

    const setClause = relSetParts.length > 0 ? ' SET ' + relSetParts.join(', ') : '';
    const safeFromId = String(rel.from_id).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
    const safeToId = String(rel.to_id).replace(/\\/g, '\\\\').replace(/'/g, "\\'");

    clauses.push(`WITH 1 AS dummy MATCH (${fromVar}:${rel.from_type} {${fromField}: '${safeFromId}'}) MATCH (${toVar}:${rel.to_type} {${toField}: '${safeToId}'}) MERGE (${fromVar})-[${relVar}:${rel.relationship_type}]->(${toVar})${setClause}`);
  }

  if (clauses.length > 0) {
    const fullQuery = clauses.join('\n') + '\nRETURN 1 AS ok';
    queries.push({ json: { queryType: 'batch', cypher: fullQuery } });
  }
}

if (queries.length === 0) {
  queries.push({ json: { queryType: 'noop', cypher: 'RETURN 1 AS ok' } });
}

return queries;

